//! The parity manifest tool.
//!
//! Invariant: the compatibility report is generated by this tool and by nothing
//! else. It reads the manifest, the source register, and whatever test results
//! have been recorded, and it exits non-zero when the manifest claims more than
//! the evidence supports.
//!
//! Usage:
//!
//! ```text
//! inillucent-manifest check                      # validate the manifest only
//! inillucent-manifest report [--results <dir>] [--out <dir>]
//! inillucent-manifest reference                  # print the pinned reference build
//! inillucent-manifest layering                   # check the dependency contract
//! ```

use std::path::PathBuf;
use std::process::ExitCode;

use inillucent_compat::layering::{self, Contract};
use inillucent_compat::manifest::{Manifest, Reference, SourceRegister};
use inillucent_compat::report;
use inillucent_compat::results::ResultSet;
use inillucent_compat::workspace_root;

/// Parses the command line and runs the requested subcommand.
fn main() -> ExitCode {
    let arguments: Vec<String> = std::env::args().skip(1).collect();
    let command = arguments.first().map(String::as_str).unwrap_or("report");
    let outcome = match command {
        "check" => run_check(),
        "report" => run_report(&arguments),
        "reference" => run_reference(),
        "verify-artifact" => run_verify_artifact(&arguments),
        "layering" => run_layering(),
        other => Err(format!("unknown command `{other}`")),
    };
    match outcome {
        Ok(()) => ExitCode::SUCCESS,
        Err(reason) => {
            eprintln!("{reason}");
            ExitCode::FAILURE
        }
    }
}

/// Returns the value of a `--flag value` argument.
fn flag(arguments: &[String], name: &str) -> Option<PathBuf> {
    let position = arguments.iter().position(|argument| argument == name)?;
    arguments.get(position.saturating_add(1)).map(PathBuf::from)
}

/// Validates the manifest without generating a report.
fn run_check() -> Result<(), String> {
    let root = workspace_root();
    let manifest = Manifest::load(&root.join("compat/sqlite-3.53.4.toml"))?;
    let sources = SourceRegister::load(&root.join("compat/sources.toml"))?;
    let generated = report::generate(&manifest, &sources, &ResultSet::default());
    let structural: Vec<_> = generated
        .problems
        .iter()
        .filter(|problem| problem.kind != "unsupported-release-claim")
        .collect();
    println!("{} capabilities", manifest.capabilities.len());
    for (status, count) in manifest.counts() {
        println!("  {status}: {count}");
    }
    if structural.is_empty() {
        return Ok(());
    }
    for problem in &structural {
        eprintln!(
            "{}: {} - {}",
            problem.kind, problem.capability, problem.detail
        );
    }
    Err(format!("{} structural problems", structural.len()))
}

/// Generates the compatibility report from the manifest and recorded results.
fn run_report(arguments: &[String]) -> Result<(), String> {
    let root = workspace_root();
    let manifest = Manifest::load(&root.join("compat/sqlite-3.53.4.toml"))?;
    let sources = SourceRegister::load(&root.join("compat/sources.toml"))?;
    let results_dir = flag(arguments, "--results").unwrap_or_else(|| root.join("compat/results"));
    let results = ResultSet::load_directory(&results_dir)?;
    let generated = report::generate(&manifest, &sources, &results);
    let out = flag(arguments, "--out").unwrap_or_else(|| root.join("compat"));
    std::fs::create_dir_all(&out)
        .map_err(|error| format!("cannot create {}: {error}", out.display()))?;
    std::fs::write(out.join("compat-report.json"), generated.to_json())
        .map_err(|error| format!("cannot write the report: {error}"))?;
    std::fs::write(out.join("compat-report.md"), generated.to_markdown())
        .map_err(|error| format!("cannot write the scorecard: {error}"))?;
    println!("reference: {}", generated.reference);
    println!("results: {} recorded", results.len());
    for (status, count) in &generated.counts {
        println!("  {status}: {count}");
    }
    println!("digest: {}", generated.digest());
    if generated.problems.is_empty() {
        return Ok(());
    }
    for problem in &generated.problems {
        eprintln!(
            "{}: {} - {}",
            problem.kind, problem.capability, problem.detail
        );
    }
    Err(format!("{} problems", generated.problems.len()))
}

/// Prints the pinned reference build, which is what a run records alongside its
/// numbers so a later comparison knows what it was comparing against.
fn run_reference() -> Result<(), String> {
    let root = workspace_root();
    let reference = Reference::load(&root.join("compat/reference/sqlite-3.53.4.toml"))?;
    println!("sqlite {} ({})", reference.version, reference.release_id);
    println!("compile options: {}", reference.compile_options);
    for (key, value) in &reference.settings {
        println!("  {key} = {value}");
    }
    for artifact in &reference.artifacts {
        println!("  {} sha3-256 {}", artifact.name, artifact.sha3_256);
    }
    Ok(())
}

/// Verifies a downloaded reference artifact against its pinned checksum.
///
/// The check is here rather than in the download script so that both platforms
/// verify with the same first-party SHA3-256, and so a script cannot quietly
/// skip the step by not having a hashing tool installed.
fn run_verify_artifact(arguments: &[String]) -> Result<(), String> {
    let name = arguments
        .get(1)
        .ok_or("verify-artifact needs an artifact name and a path")?;
    let path = arguments
        .get(2)
        .ok_or("verify-artifact needs an artifact name and a path")?;
    let root = workspace_root();
    let reference = Reference::load(&root.join("compat/reference/sqlite-3.53.4.toml"))?;
    let artifact = reference
        .artifact(name)
        .ok_or_else(|| format!("`{name}` is not a pinned artifact"))?;
    let bytes = std::fs::read(path).map_err(|error| format!("cannot read {path}: {error}"))?;
    if bytes.len() as u64 != artifact.bytes {
        return Err(format!(
            "{name}: expected {} bytes, found {}",
            artifact.bytes,
            bytes.len()
        ));
    }
    let digest = inillucent_compat::hash::sha3_256_hex(&bytes);
    if digest != artifact.sha3_256 {
        return Err(format!(
            "{name}: expected sha3-256 {}, found {digest}",
            artifact.sha3_256
        ));
    }
    println!("{name}: {} bytes, sha3-256 {digest}", bytes.len());
    Ok(())
}

/// Checks the workspace against the dependency-direction contract.
fn run_layering() -> Result<(), String> {
    let root = workspace_root();
    let contract = Contract::load(&root.join("docs/invariants/layering.toml"))?;
    let manifests = layering::read_workspace(&root)?;
    let violations = layering::check(&contract, &manifests);
    println!("{} crates checked", manifests.len());
    if violations.is_empty() {
        return Ok(());
    }
    for violation in &violations {
        eprintln!("{violation}");
    }
    Err(format!("{} layering violations", violations.len()))
}
